package com.paymesh.backend.chat;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.*;
import java.math.BigDecimal;
import java.util.*;
import java.util.regex.Pattern;
/** Independent verification of Python's finite approved financial answers, not semantic trust in free text. */
public final class ChatRules {
 private static final ObjectMapper JSON=new ObjectMapper();public static final JsonNode CONTRACT;
 static{try(var in=ChatRules.class.getResourceAsStream("/ai-chat/contract.json")){if(in==null)throw new IllegalStateException();CONTRACT=JSON.readTree(in);}catch(Exception e){throw new ExceptionInInitializerError("Chat contract manifest missing");}}
 public record Expected(String answer,String intent,String topic,List<String> refs,ArrayNode money,List<String> limitations){}
 private static boolean has(String q,String pattern){return Pattern.compile(pattern,Pattern.CASE_INSENSITIVE).matcher(q).find();}
 public static String[] resolve(JsonNode req){
  String q=req.path("question").asText().toLowerCase(Locale.ROOT).strip();JsonNode rules=CONTRACT.path("routing");
  boolean concept=has(q,rules.path("concept").asText())&&!has(q,rules.path("personal").asText());
  if(has(q,"ignore.{0,40}(instructions|rules|previous)|system prompt|developer prompt|\\b(password|secret|cvv|otp|sql|shell)\\b|other merchant|another merchant|\\b(select|drop|delete)\\s+.*\\b(from|table)\\b")||has(q,"^(please\\s+)?(refund|pay|charge|process|create|cancel|approve|suspend|execute|run|transfer|delete|update)\\b|\\b(do it now|refund it now|make a payment)\\b")||has(q,"\\b(i want you to|can you|could you|would you)\\s+(please\\s+)?(refund|pay|process|create|cancel|transfer|execute)\\b")||has(q,"\\b[0-9a-f]{8}(?:-[0-9a-f]{4}){3}-[0-9a-f]{12}\\b"))return new String[]{"UNSUPPORTED","lifecycle"};
  if(has(q,rules.path("unsupportedQuery").asText()))return new String[]{"INSUFFICIENT_EVIDENCE","lifecycle"};
  List<List<String>> candidates=new ArrayList<>();for(JsonNode row:rules.path("topics"))if(has(q,row.get(2).asText())){var candidate=List.of(row.get(0).asText(),row.get(1).asText());if(!candidates.contains(candidate))candidates.add(candidate);}
  if(candidates.size()>1){var specific=candidates.stream().filter(c->!c.get(0).equals("lifecycle")).toList();if(!specific.isEmpty())candidates=new ArrayList<>(specific);}
  if(candidates.stream().anyMatch(c->c.get(0).equals("timeout")))candidates.removeIf(c->c.get(0).equals("routing"));
  if(candidates.stream().anyMatch(c->c.get(0).equals("refunds")))candidates.removeIf(c->Set.of("failure","statistics").contains(c.get(0)));
  if(candidates.stream().anyMatch(c->c.get(0).equals("api"))&&candidates.stream().anyMatch(c->c.get(0).equals("security")))candidates.removeIf(c->c.get(0).equals("api"));
  if(candidates.contains(List.of("lifecycle","PAYMENT_STATUS")))candidates.remove(List.of("lifecycle","KNOWLEDGE"));
  if(Pattern.compile(rules.path("follow").asText()).matcher(q).matches()&&candidates.isEmpty()){
   JsonNode h=req.path("history");for(int i=h.size()-1;i>=0;i--)if(h.get(i).path("role").asText().equals("user")){
    var previous=resolve(JSON.createObjectNode().put("question",h.get(i).path("content").asText()));
    if(!Set.of("UNSUPPORTED","INSUFFICIENT_EVIDENCE").contains(previous[0])){var p=req.path("evidence").path("payment");if(q.startsWith("why")&&p.isObject()&&!Set.of("KNOWLEDGE","STATISTICS","CHECKOUT").contains(previous[0]))return switch(p.path("status").asText()){case "FAILED"->new String[]{"PAYMENT_FAILURE","failure"};case "PROCESSING"->new String[]{"PROCESSING","timeout"};default->new String[]{"PAYMENT_STATUS","lifecycle"};};return previous;}break;
   }
  }
  if(candidates.size()!=1)return new String[]{"INSUFFICIENT_EVIDENCE","lifecycle"};var chosen=candidates.getFirst();String topic=chosen.get(0),intent=chosen.get(1);if(concept)intent="KNOWLEDGE";else if(intent.equals("KNOWLEDGE")&&topic.equals("lifecycle"))return new String[]{"INSUFFICIENT_EVIDENCE","lifecycle"};return new String[]{intent,topic};
 }
 private static final class Build {String intent,topic;List<String> refs=new ArrayList<>(),limits=new ArrayList<>();ArrayNode money=JSON.createArrayNode();Build(String[] r){intent=r[0];topic=r[1];CONTRACT.path("limitations").forEach(n->limits.add(n.asText()));}void ref(JsonNode n){refs.add(n.path("ref").asText());}void amount(String kind,String amount,String currency,Long count){var n=money.addObject();n.put("kind",kind);n.put("amount",amount);n.put("currency",currency);if(count==null)n.putNull("count");else n.put("count",count);}Expected done(String text,JsonNode evidence){for(JsonNode u:evidence.path("unavailableEvidence"))limits.add(u.asText()+" evidence is unavailable; it is not proof that no event occurred.");return new Expected(text,intent,topic,List.copyOf(new LinkedHashSet<>(refs)),money,List.copyOf(limits));}}
 private static java.math.BigInteger units(String text){if(!text.matches("(0|[1-9][0-9]{0,23})\\.[0-9]{2}"))throw unsupported();return new BigDecimal(text).movePointRight(2).toBigIntegerExact();}
 private static String money(java.math.BigInteger value){if(value.signum()<0)throw unsupported();return new BigDecimal(value,2).toPlainString();}
 private static ChatFailure unsupported(){return new ChatFailure(422,"UNSUPPORTED_EVIDENCE","Authorized evidence is inconsistent with the chat contract.");}
 public static Expected expected(JsonNode req){var raw=rawExpected(req);return new Expected(CustomerWording.render(req,raw),raw.intent(),raw.topic(),raw.refs(),raw.money(),raw.limitations());}
 private static Expected rawExpected(JsonNode req){var b=new Build(resolve(req));JsonNode e=req.path("evidence"),p=e.path("payment");String intent=b.intent,status=p.path("status").asText(),currency=p.path("currency").asText(),amount=p.path("amount").asText();
  if(p.isObject()){var total=java.math.BigInteger.ZERO;for(JsonNode r:e.path("refunds"))total=total.add(units(r.path("amount").asText()));if(total.compareTo(units(amount))>0||total.signum()>0&&!Set.of("SUCCESS","REFUNDED").contains(status)||e.path("refundHistoryComplete").asBoolean()&&(status.equals("REFUNDED")!=total.equals(units(amount))))throw unsupported();}
  if(intent.equals("UNSUPPORTED"))return b.done("I cannot execute financial actions, retrieve arbitrary records, establish ownership, disclose secrets or change authorization. Use the authorized Java workflows for any action.",e);
  if(intent.equals("INSUFFICIENT_EVIDENCE"))return b.done("Please clarify the payment-domain topic or select an authorized payment for its recorded status, gateway or refunds. Latest/recent payment selection and daily trends are not supported by this chat evidence contract. Prior assistant statements cannot supply missing facts.",e);
  if(intent.equals("KNOWLEDGE"))return b.done("General project guidance, not evidence of a transaction: "+CONTRACT.path("policies").path(b.topic).get(3).asText(),e);
  if(intent.equals("CHECKOUT")){var c=e.path("checkout");if(!c.isObject())return b.done("No current authorized checkout snapshot was supplied. I cannot determine whether this link is payable, expired, cancelled, paid or unresolved.",e);b.ref(c);b.amount("CHECKOUT_AMOUNT",c.path("amount").asText(),c.path("currency").asText(),null);String s=c.path("status").asText();String detail=switch(s){case "PROCESSING"->"An accepted attempt is unresolved; do not create another payment or retry the gateway.";case "UNCERTAIN"->"The outcome is unknown, not confirmed failure; check authorized status and reconciliation evidence.";case "PAID"->"This link has a successful payment association; it must not execute again, even after refund.";case "FAILED"->"A new attempt requires definitive failure and a fresh Java eligibility/expiry/attempt-limit check.";case "EXPIRED","CANCELLED"->"The link cannot initiate a new payment.";case "UNAVAILABLE"->"The snapshot does not establish eligibility for initiation.";case "ACTIVE"->"ACTIVE alone does not authorize an action; Java must recheck current eligibility and expiry.";default->throw unsupported();};return b.done("The supplied checkout snapshot records "+s+", fixed amount "+c.path("amount").asText()+" "+c.path("currency").asText()+", method "+c.path("paymentMethod").asText()+". "+detail,e);}
  if(intent.equals("STATISTICS")){var stats=e.path("statistics");if(!stats.isArray())return b.done("Authorized aggregate statistics were not supplied. Recent records cannot establish complete totals, balance, settlement, revenue or profit.",e);stats.forEach(b::ref);boolean complete=e.path("statisticsComplete").asBoolean();List<String> lines=new ArrayList<>();for(JsonNode cur:e.path("statisticsCurrencies"))for(String kind:List.of("PAYMENT","REFUND")){List<JsonNode> rows=new ArrayList<>();for(JsonNode r:stats)if(r.path("currency").asText().equals(cur.asText())&&r.path("kind").asText().equals(kind))rows.add(r);if(rows.isEmpty()&&!complete)continue;java.math.BigInteger sum=java.math.BigInteger.ZERO;long count=0;List<String> detail=new ArrayList<>();for(var r:rows){sum=sum.add(units(r.path("amount").asText()));count+=r.path("count").longValue();detail.add(r.path("status").asText()+": "+r.path("count").asText()+", "+r.path("amount").asText()+" "+cur.asText()+".");}b.amount(kind+"_AGGREGATE",money(sum),cur.asText(),count);lines.add(cur.asText()+" recorded "+kind.toLowerCase(Locale.ROOT)+" aggregates: count "+count+", amount "+money(sum)+". "+String.join(" ",detail));}b.limits.add("Aggregate completeness and scope are supplied by Java, not independently verified by Python.");if(!complete)b.limits.add("Aggregate groups are not confirmed complete; these are supplied-cell subtotals, not full dashboard totals.");return b.done((complete?"Complete supplied-scope aggregates. ":"Supplied aggregate-cell subtotals only. ")+String.join(" ",lines)+" Currencies and payments/refunds remain separate; these are not balance, settlement, revenue or profit.",e);}
  if(!p.isObject())return b.done("A current authorized payment snapshot was not supplied. I cannot infer its status, cause, refund amount or gateway history from conversation alone.",e);b.ref(p);
  if(intent.equals("REFUND_SUMMARY")){b.amount("ORIGINAL_PAYMENT",amount,currency,null);var rs=e.path("refunds");if(!rs.isArray())return b.done("The supplied payment amount is "+amount+" "+currency+". Refund history is unavailable; successful refund totals and remaining amount are not established.",e);java.math.BigInteger sum=java.math.BigInteger.ZERO;for(var r:rs){b.ref(r);sum=sum.add(units(r.path("amount").asText()));}boolean complete=e.path("refundHistoryComplete").asBoolean();if(!rs.isEmpty()||complete)b.amount("OBSERVED_SUCCESSFUL_REFUNDS",money(sum),currency,null);if(!complete)return b.done("Original payment: "+amount+" "+currency+". "+(!rs.isEmpty()?"Observed successful refunds in supplied rows: "+money(sum)+" "+currency+". ":"No complete refund total is established. ")+"Refund history is not confirmed complete; the remaining refundable amount is unknown. Do not infer another refund is allowed.",e);if(!Set.of("SUCCESS","REFUNDED").contains(status))return b.done("The recorded payment status is "+status+", which is not refund eligible. No refundable remaining amount is inferred from this lifecycle.",e);var remaining=units(amount).subtract(sum);b.amount("REMAINING_REFUNDABLE",money(remaining),currency,null);return b.done("Original payment: "+amount+" "+currency+"; recorded successful refunds: "+money(sum)+" "+currency+"; remaining recorded amount: "+money(remaining)+" "+currency+". "+(!status.equals("SUCCESS")||remaining.signum()==0?"The supplied lifecycle is not eligible for a new refund. ":"Java must recheck current authorization, eligibility and cumulative limits before any refund. ")+"This is exact snapshot arithmetic, not authorization or evidence of bank refund arrival.",e);}
  if(intent.equals("GATEWAY")){var gs=e.path("gateways");if(!gs.isArray())return b.done("The payment records "+status+", but gateway evidence is unavailable. Currency/routing does not prove a gateway transaction occurred.",e);gs.forEach(b::ref);List<String> observations=new ArrayList<>();gs.forEach(g->observations.add(g.path("gatewayName").asText()+" "+g.path("status").asText()));return b.done("The payment row records "+status+". "+(gs.isEmpty()?"No gateway records were supplied. Absence does not prove no event occurred.":"Supplied gateway observations: "+String.join(", ",observations)+". Gateway observations are not a confirmed root cause or independent proof of bank settlement. Current mutable success records do not prove a historical timeout."),e);}
  if(intent.equals("PAYMENT_FAILURE"))return b.done("The current payment snapshot records "+status+". "+(status.equals("FAILED")?"The failure cause is not established by a FAILED status alone; no specific technical or bank cause is inferred.":"This does not establish a prior failed payment or its cause."),e);
  if(intent.equals("PROCESSING")){if(!status.equals("PROCESSING"))return b.done("The current payment snapshot records "+status+", not PROCESSING. No previous timeout or recovery event is inferred.",e);var gs=e.path("gateways");List<String> observations=new ArrayList<>();gs.forEach(g->{b.ref(g);observations.add(g.path("status").asText());});return b.done("The payment is currently PROCESSING. "+(!observations.isEmpty()?"Supplied gateway observations include "+String.join(", ",observations)+". ":"No gateway cause is established. ")+"Timeout/unknown does not mean failure. Do not retry the gateway or create a replacement while unresolved; use authorized status and reconciliation review.",e);}
  String detail=switch(status){case "CREATED"->"Processing has not started.";case "PROCESSING"->"The outcome is unresolved; do not initiate a duplicate payment.";case "SUCCESS"->"A successful simulated payment is recorded; no prior failure, timeout or recovery is inferred.";case "FAILED"->"A failed payment is recorded; the underlying cause is not established.";case "CANCELLED"->"The payment is recorded as cancelled; no future outcome is guaranteed.";case "REFUNDED"->"The payment is recorded as fully refunded; complete successful refund history is needed to corroborate totals.";default->throw unsupported();};return b.done("The supplied current payment status is "+status+". "+detail,e);
 }
}
